// ============================================================
//  CONFIGURATION — à adapter avant d'activer le workflow
// ============================================================
const CONFIG = {
  brand: 'Portefolia',
  tagline: 'Expose ton futur.',
  domain: 'portefolia.tech',
  frontUrl: 'https://portefolia.tech',
  apiUrl: 'https://portefolia.tech/api',          // ou http://localhost:<port>/api si n8n tourne sur le même VPS
  fromEmail: 'Portefolia <support@portefolia.tech>',
  replyTo: 'support@portefolia.tech',
  adminEmail: 'diankaseydou52@gmail.com',       // boîte qui reçoit les alertes admin
  supportWhatsapp: '+221 78 131 13 71',
  colors: { primary: '#1B5E20', accent: '#2E7D32' }, // vert Portefolia
  telegram: { enabled: false, chatId: '' },          // alertes admin sur Telegram (optionnel)
  whatsapp: {                                        // WhatsApp Cloud API (optionnel, templates approuvés par Meta)
    enabled: false,
    phoneNumberId: '',
    templates: { created: 'precommande_recue', paid: 'precommande_confirmee' },
  },
};
return $input.all().map((i) => ({ json: { ...i.json, config: CONFIG } }));

// ---------- Helpers (échappement, format, gabarit e-mail) ----------
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fcfa = (n) => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' F CFA';
const firstName = (p) => (p.first_name || String(p.full_name || '').trim().split(/\s+/)[0] || '').trim();
const para = (html) => `<p style="font-size:15px;line-height:1.6;margin:0 0 12px">${html}</p>`;
const row = (k, v) => `<tr><td style="padding:7px 0;color:#6b7280;width:45%;vertical-align:top">${esc(k)}</td><td style="padding:7px 0;font-weight:600">${v}</td></tr>`;
const table = (rows) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:14px;border-top:1px solid #e5e7eb;border-bottom:1px solid #e5e7eb;margin:16px 0">${rows.join('')}</table>`;
const hoursSince = (iso) => (iso ? Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 36e5)) : null);

function layout(cfg, { preheader = '', title, body, cta }) {
  const button = cta && cta.url
    ? `<p style="margin:28px 0 8px;text-align:center"><a href="${esc(cta.url)}" style="background:${cfg.colors.accent};color:#ffffff;text-decoration:none;padding:14px 26px;border-radius:8px;font-weight:600;display:inline-block">${esc(cta.label)}</a></p>`
    : '';
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title></head>
<body style="margin:0;background:#f4f5f7;font-family:Arial,Helvetica,sans-serif;color:#1f2937">
<span style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(preheader)}</span>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;overflow:hidden">
<tr><td style="background:${cfg.colors.primary};padding:22px 28px;color:#ffffff;font-size:20px;font-weight:700">${esc(cfg.brand)}<div style="font-size:12px;font-weight:400;opacity:.85;margin-top:4px">${esc(cfg.tagline)}</div></td></tr>
<tr><td style="padding:28px">
<h1 style="font-size:20px;line-height:1.3;margin:0 0 16px">${esc(title)}</h1>
${body}
${button}
</td></tr>
<tr><td style="padding:18px 28px;background:#f9fafb;font-size:12px;line-height:1.5;color:#6b7280">Vous recevez cet e-mail suite à votre précommande sur ${esc(cfg.domain)}. Une question ? Répondez à cet e-mail ou écrivez-nous sur WhatsApp au ${esc(cfg.supportWhatsapp)}.</td></tr>
</table></td></tr></table></body></html>`;
}

function waveBlock(p, pay) {
  return `<div style="background:#eef6ff;border-radius:10px;padding:16px 18px;margin:16px 0;font-size:14px;line-height:1.7">
<strong>Comment payer avec Wave</strong><br>
1. Envoyez <strong>${esc(fcfa(p.total_amount))}</strong> au <strong>${esc(pay.wave_number)}</strong>${pay.wave_link ? ` ou passez par <a href="${esc(pay.wave_link)}">ce lien de paiement Wave</a>` : ''}.<br>
2. Mettez la référence <strong>${esc(p.reference)}</strong> en note du transfert.<br>
3. Cliquez sur le bouton ci-dessous et saisissez l'identifiant de la transaction Wave (visible dans l'historique de l'application).
</div>`;
}

function recap(p, extra = []) {
  return table([
    row('Référence', esc(p.reference)),
    row('Offre', esc('Carte ' + (p.offer_name || 'Standard'))),
    row('Nom imprimé sur la carte', esc(p.card_name)),
    row('Quantité', esc(p.quantity)),
    row('Montant total', esc(fcfa(p.total_amount))),
    ...extra,
  ]);
}

// ---------- Construction des messages selon l'événement ----------
const out = [];

for (const item of $input.all()) {
  const cfg = item.json.config;
  const b = item.json.body || {};
  const p = b.preorder || {};
  const pay = b.payment || {};
  const stats = b.stats || {};
  const links = b.links || {};
  // Événements sans précommande : stock, lot d'impression, carte perdue, devis Entreprise
  const generic = genericMessage(cfg, b);
  if (generic) { out.push({ json: generic }); continue; }
  if (!b.event || !p.id || !p.email) continue; // payload invalide : on ignore

  const prenom = esc(firstName(p));
  let client = null;
  let admin = null;
  let whatsapp = null;

  const adminRows = [
    row('Référence', esc(p.reference)),
    row('Offre', esc('Carte ' + (p.offer_name || 'Standard'))),
    row('Client', esc(p.full_name)),
    row('E-mail', esc(p.email)),
    row('Téléphone', esc(p.phone)),
    row('Nom sur la carte', esc(p.card_name)),
    row('Quantité', esc(p.quantity)),
    row('Montant', esc(fcfa(p.total_amount))),
  ];
  const lot = stats.batch_threshold ? `${stats.paid_count || 0}/${stats.batch_threshold}` : String(stats.paid_count || 0);

  switch (b.event) {
    case 'preorder.created': {
      const subject = `Commande ${p.reference} (carte ${p.offer_name || 'Standard'}) reçue – finalisez votre paiement Wave`;
      client = { subject, html: layout(cfg, {
        preheader: `Payez ${fcfa(p.total_amount)} avec Wave pour réserver votre carte NFC.`,
        title: `Merci ${prenom}, votre commande est enregistrée`,
        body: para('Votre carte NFC Portefolia est presque réservée. Il ne reste qu\'une étape : le paiement Wave.')
          + recap(p) + waveBlock(p, pay)
          + para('<span style="color:#6b7280;font-size:13px">Sans paiement sous 72 h, la précommande est annulée automatiquement. Vous pourrez en refaire une à tout moment.</span>'),
        cta: { label: 'Déclarer mon paiement Wave', url: links.tracking_url },
      }) };
      admin = {
        subject: `🆕 Commande ${p.reference} — carte ${p.offer_name || 'Standard'} — ${fcfa(p.total_amount)}`,
        html: layout(cfg, { title: 'Nouvelle commande de carte NFC', body: table(adminRows) + para('Statut : en attente du paiement Wave.'), cta: { label: 'Ouvrir dans l\'admin', url: links.admin_url } }),
        text: `🆕 <b>Nouvelle commande ${esc(p.reference)}</b> — carte ${esc(p.offer_name || 'Standard')}\n${esc(p.full_name)} — ${esc(p.phone)}\n${esc(p.quantity)} carte(s) — ${esc(fcfa(p.total_amount))}`,
      };
      if (cfg.whatsapp.enabled && cfg.whatsapp.templates.created) {
        whatsapp = { template: cfg.whatsapp.templates.created, params: [firstName(p), p.reference, fcfa(p.total_amount)] };
      }
      break;
    }

    case 'preorder.payment_submitted': {
      client = { subject: `Paiement Wave reçu pour ${p.reference} – vérification en cours`, html: layout(cfg, {
        preheader: 'Nous vérifions votre transaction Wave.',
        title: `Merci ${prenom}, nous vérifions votre paiement`,
        body: para('Nous avons bien reçu votre déclaration de paiement. Nous la vérifions et vous confirmons sous 24 h ouvrées.')
          + recap(p, [row('Transaction Wave', esc(p.wave_transaction_id))]),
        cta: { label: 'Suivre ma précommande', url: links.tracking_url },
      }) };
      admin = {
        subject: `⏳ Paiement Wave à valider — ${p.reference}`,
        html: layout(cfg, { title: 'Paiement Wave à vérifier', body:
          para('Vérifiez la transaction dans Wave Business, puis validez ou refusez dans l\'admin.')
          + table([...adminRows, row('ID transaction Wave', esc(p.wave_transaction_id)), row('Numéro Wave payeur', esc(p.wave_sender_phone || '—'))]),
          cta: { label: 'Valider le paiement', url: links.admin_url } }),
        text: `⏳ <b>Paiement à valider ${esc(p.reference)}</b>\n${esc(p.full_name)} — ${esc(fcfa(p.total_amount))}\nTransaction : <code>${esc(p.wave_transaction_id)}</code>`,
      };
      break;
    }

    case 'preorder.paid': {
      client = { subject: '✅ Paiement confirmé – votre carte NFC Portefolia est lancée', html: layout(cfg, {
        preheader: `Commande ${p.reference} confirmée.`,
        title: `C'est confirmé, ${prenom} !`,
        body: para('Nous avons validé votre paiement Wave.')
          + recap(p)
          + para('<strong>La suite :</strong> vous recevez le bon à tirer (BAT) de votre carte, à valider en ligne avant l\'impression à Dakar. Nous vous prévenons ensuite à chaque étape, jusqu\'à la remise de la carte.')
          + para('En attendant, préparez votre portfolio : c\'est lui qui s\'affichera quand quelqu\'un approchera son téléphone de votre carte.'),
        cta: { label: 'Suivre ma commande', url: links.tracking_url },
      }) };
      if (whatsappEnabled(cfg, 'paid')) {
        whatsapp = { template: cfg.whatsapp.templates.paid, params: [firstName(p), p.reference] };
      }
      break;
    }

    case 'preorder.rejected': {
      client = { subject: `Paiement non confirmé pour la précommande ${p.reference}`, html: layout(cfg, {
        preheader: 'Nous n\'avons pas pu confirmer votre paiement Wave.',
        title: `${prenom}, nous n'avons pas pu confirmer votre paiement`,
        body: para(`Motif : <strong>${esc(p.rejection_reason || 'transaction introuvable ou montant différent')}</strong>.`)
          + para('Votre précommande reste ouverte. Vérifiez la transaction puis déclarez-la à nouveau, ou répondez à cet e-mail si vous pensez qu\'il s\'agit d\'une erreur.')
          + waveBlock(p, pay),
        cta: { label: 'Déclarer à nouveau mon paiement', url: links.tracking_url },
      }) };
      break;
    }

    case 'preorder.expired':
    case 'preorder.cancelled': {
      const expired = b.event === 'preorder.expired';
      client = { subject: `Précommande ${p.reference} annulée${expired ? ' (paiement non reçu)' : ''}`, html: layout(cfg, {
        title: `${prenom}, votre précommande a été annulée`,
        body: para(expired
          ? 'Nous n\'avons pas reçu de paiement Wave dans les 72 h, la précommande a donc été annulée.'
          : `Votre précommande ${esc(p.reference)} a été annulée${p.rejection_reason ? ` (motif : ${esc(p.rejection_reason)})` : ''}.`)
          + para('Vous pouvez refaire une précommande à tout moment.'),
        cta: { label: 'Refaire une précommande', url: links.preorder_url || cfg.frontUrl + '/nfc-types' },
      }) };
      break;
    }

    case 'order.design_started': {
      client = { subject: `Votre carte ${p.reference} est entre les mains de notre designer`, html: layout(cfg, {
        title: `${prenom}, nous préparons votre carte`,
        body: para(p.bat_comment
          ? `Nous appliquons votre demande de correction : « ${esc(p.bat_comment)} ». Vous recevez un nouveau bon à tirer très vite.`
          : 'Notre équipe prépare le visuel de votre carte. Vous recevrez un bon à tirer (BAT) à valider avant l\'impression, généralement sous 48 h ouvrées.')
          + recap(p),
        cta: { label: 'Suivre ma commande', url: links.tracking_url },
      }) };
      break;
    }

    case 'bat.sent': {
      const bat = b.bat || {};
      const imgs = [bat.front_url, bat.back_url].filter(Boolean)
        .map((u) => `<img src="${esc(u)}" alt="Bon à tirer" width="504" style="display:block;width:100%;max-width:504px;border-radius:10px;margin:0 0 10px;border:1px solid #e5e7eb">`).join('');
      client = { subject: `🖨️ Votre bon à tirer est prêt – carte ${p.reference}`, html: layout(cfg, {
        preheader: 'Vérifiez et validez le visuel de votre carte avant impression.',
        title: `${prenom}, validez votre bon à tirer`,
        body: para('Voici le visuel final de votre carte. Vérifiez attentivement l\'orthographe, le numéro de téléphone et les couleurs : la carte sera imprimée exactement ainsi.')
          + imgs
          + para('Validez-le, ou demandez une correction, depuis votre page de suivi.'),
        cta: { label: 'Valider mon bon à tirer', url: links.tracking_url },
      }) };
      break;
    }

    case 'bat.changes_requested': {
      admin = {
        subject: `✏️ Correction demandée sur le BAT — ${p.reference}`,
        html: layout(cfg, { title: 'Correction de BAT demandée', body: para(`« ${esc(p.bat_comment || '')} »`) + table(adminRows), cta: { label: 'Ouvrir la commande', url: links.admin_url } }),
        text: `✏️ <b>Correction BAT ${esc(p.reference)}</b>\n${esc(p.bat_comment || '')}`,
      };
      break;
    }

    case 'order.printing': {
      client = { subject: `Votre carte ${p.reference} est en impression`, html: layout(cfg, {
        title: `${prenom}, votre carte est en impression`,
        body: para('Votre bon à tirer est validé et votre carte est en cours d\'impression à Dakar. Nous vous prévenons dès qu\'elle est prête.') + recap(p),
        cta: { label: 'Suivre ma commande', url: links.tracking_url },
      }) };
      break;
    }

    case 'order.ready': {
      client = { subject: `🎉 Votre carte NFC ${p.reference} est prête`, html: layout(cfg, {
        preheader: 'Votre carte est prête et déjà active.',
        title: `${prenom}, votre carte est prête !`,
        body: para('Bonne nouvelle : votre carte NFC Portefolia est imprimée. Elle est déjà active : approchez un téléphone pour ouvrir votre portfolio.')
          + para(`Nous vous contactons sur WhatsApp pour la remise. Une question ? Écrivez-nous au ${esc(cfg.supportWhatsapp)}.`)
          + recap(p),
        cta: { label: 'Suivre ma commande', url: links.tracking_url },
      }) };
      break;
    }

    case 'order.delivered': {
      client = { subject: `Carte NFC ${p.reference} livrée – bonne utilisation !`, html: layout(cfg, {
        title: `Merci ${prenom} !`,
        body: para('Votre carte NFC Portefolia vous a été remise. Depuis votre espace, vous pouvez choisir le portfolio qu\'elle ouvre (sans la réimprimer), voir le nombre de taps, ou la désactiver en cas de perte.'),
        cta: { label: 'Gérer mes cartes', url: cfg.frontUrl + '/dashboard/nfc-cards' },
      }) };
      break;
    }

    default:
      continue; // événement inconnu (ou sans e-mail, ex. bat.approved) : rien à envoyer
  }

if (b.audience === 'client') admin = null;

  out.push({ json: {
    event_id: b.event_id || null,
    event: b.event,
    preorder_id: p.id,
    reference: p.reference,
    apiUrl: cfg.apiUrl,
    from: cfg.fromEmail,
    replyTo: cfg.replyTo,
    client: client ? { to: p.email, ...client } : null,
    admin: admin ? { to: cfg.adminEmail, ...admin } : null,
    telegram: admin && cfg.telegram.enabled ? { chatId: cfg.telegram.chatId } : null,
    whatsapp: whatsapp ? { to: String(p.phone || '').replace(/\D/g, ''), phoneNumberId: cfg.whatsapp.phoneNumberId, ...whatsapp } : null,
  } });
}

function whatsappEnabled(cfg, key) { return cfg.whatsapp.enabled && !!cfg.whatsapp.templates[key]; }

// Événements sans précommande : un objet de sortie, ou null si l'événement n'est pas de ce type
function genericMessage(cfg, b) {
  const L = b.links || {};
  let admin = null;
  let client = null;
  let clientTo = null;
  let reference = null;

  switch (b.event) {
    case 'stock.low': {
      const s = b.stock || {};
      admin = {
        subject: `📦 Stock bas : cartes « ${s.label} » (${s.available} restante(s))`,
        html: layout(cfg, { title: 'Stock de cartes sous le seuil', body:
          para(`Il reste <strong>${esc(s.available)}</strong> carte(s) « ${esc(s.label)} » en stock (seuil d'alerte : ${esc(s.threshold)}).`)
          + para('Pensez à commander un nouveau lot : générez les codes depuis « Stock & codes NFC » et envoyez le fichier au fournisseur.'),
          cta: { label: 'Voir le stock', url: L.admin_stock_url } }),
        text: `📦 <b>Stock bas</b> : ${esc(s.label)} — ${esc(s.available)} restante(s)`,
      };
      break;
    }
    case 'print_batch.ready': {
      const pr = b.print || {};
      admin = {
        subject: `🖨️ Lot d'impression prêt : ${pr.cards} carte(s) au BAT validé`,
        html: layout(cfg, { title: 'Lot d\'impression prêt', body:
          para(`<strong>${esc(pr.cards)}</strong> carte(s) ont un bon à tirer validé (seuil : ${esc(pr.threshold)}).`)
          + para('Téléchargez le PDF imprimeur depuis l\'admin, puis lancez l\'impression à Dakar.'),
          cta: { label: 'Ouvrir la file d\'impression', url: L.admin_production_url } }),
        text: `🖨️ <b>Lot d'impression prêt</b> : ${esc(pr.cards)} carte(s)`,
      };
      break;
    }
    case 'card.reported_lost': {
      const cd = b.card || {};
      admin = {
        subject: `🚫 Carte ${cd.code} déclarée perdue`,
        html: layout(cfg, { title: 'Carte déclarée perdue', body:
          para(`La carte <strong>${esc(cd.code)}</strong> a été désactivée par son titulaire (${esc(cd.reason || 'perte ou vol')}).`)
          + para('Proposez-lui une carte de remplacement si besoin.'),
          cta: { label: 'Voir la carte', url: L.admin_stock_url } }),
        text: `🚫 Carte ${esc(cd.code)} déclarée perdue`,
      };
      break;
    }
    case 'quote.requested':
    case 'quote.sent':
    case 'quote.accepted':
    case 'quote.declined': {
      const q = b.quote || {};
      reference = q.reference || null;
      const rows = table([
        row('Devis', esc(q.reference)),
        row('Entreprise', esc(q.company)),
        row('Contact', esc(q.contact_name)),
        row('E-mail', esc(q.email)),
        row('Téléphone', esc(q.phone)),
        row('Nombre de cartes', esc(q.quantity)),
        ...(q.total_amount ? [row('Prix par carte', esc(fcfa(q.price_per_card))), row('Total', esc(fcfa(q.total_amount)))] : []),
      ]);
      if (b.event === 'quote.requested') {
        admin = {
          subject: `🏢 Demande de devis Entreprise — ${q.company} (${q.quantity} cartes)`,
          html: layout(cfg, { title: 'Nouvelle demande de devis', body: rows + (q.message ? para(`« ${esc(q.message)} »`) : ''), cta: { label: 'Chiffrer le devis', url: L.admin_quote_url } }),
          text: `🏢 <b>Devis demandé</b> : ${esc(q.company)} — ${esc(q.quantity)} cartes`,
        };
      } else if (b.event === 'quote.sent') {
        clientTo = q.email;
        client = { subject: `Votre devis Portefolia ${q.reference} — ${q.quantity} cartes NFC`, html: layout(cfg, {
          preheader: `Devis de ${fcfa(q.total_amount)} pour ${q.quantity} cartes NFC.`,
          title: `Bonjour ${esc(String(q.contact_name || '').split(' ')[0])}, voici votre devis`,
          body: para(`Merci pour votre intérêt pour les cartes NFC Portefolia pour ${esc(q.company)}.`)
            + rows
            + (q.admin_message ? para(esc(q.admin_message)) : '')
            + (q.valid_until ? para(`<span style="color:#6b7280;font-size:13px">Devis valable jusqu'au ${esc(new Date(q.valid_until).toLocaleDateString('fr-FR'))}.</span>`) : ''),
          cta: { label: 'Consulter et accepter le devis', url: L.quote_url },
        }) };
      } else {
        const ok = b.event === 'quote.accepted';
        admin = {
          subject: `${ok ? '✅ Devis accepté' : '❌ Devis refusé'} — ${q.company} (${q.reference})`,
          html: layout(cfg, { title: ok ? 'Devis accepté' : 'Devis refusé', body: rows + (ok ? para('La commande est créée : le client va payer par Wave. Préparez ensuite le design des cartes de l\'équipe.') : (q.message ? para(`Motif : « ${esc(q.message)} »`) : '')), cta: { label: 'Ouvrir le devis', url: L.admin_quote_url } }),
          text: `${ok ? '✅' : '❌'} Devis ${esc(q.reference)} ${ok ? 'accepté' : 'refusé'} — ${esc(q.company)}`,
        };
      }
      break;
    }
    default:
      return null;
  }

  return {
    event_id: b.event_id || null,
    event: b.event,
    preorder_id: null,
    reference,
    apiUrl: cfg.apiUrl,
    from: cfg.fromEmail,
    replyTo: cfg.replyTo,
    client: client && clientTo ? { to: clientTo, ...client } : null,
    admin: admin ? { to: cfg.adminEmail, ...admin } : null,
    telegram: admin && cfg.telegram.enabled ? { chatId: cfg.telegram.chatId } : null,
    whatsapp: null,
  };
}

return out;
